// ============================================================================
// SYS — consultar_catalogo · Classify Intent v3
// Fix bug "Cama Plana Huenú HF6090" (NOT_FOUND) — campaña Meta 2026-06-24
// ============================================================================
// Cambios vs v2:
//   - Normaliza acentos: "Huenú" → "huenu" antes de matchear marca.
//   - Extrae también `formato` (Cama Plana, Rollo a Rollo, Híbrido, ...).
//   - Extrae `modelo_hint` con regex (HF6090, HR 1602, DLI-1688, ...).
//   - Arma las 3 fórmulas filterByFormula (equipos/aplicaciones/inventario)
//     y las pasa por contexto a los nodos Airtable downstream.
//   - Tokeniza + remueve stopwords para fallback robusto.
// ============================================================================

const args = $input.first().json;
const raw = String(args.query || '').trim();
const sessionId = String(args.session_id || 'unknown');

// --- 0) Skip si query vacía -------------------------------------------------
if (!raw) {
  return [{ json: {
    _skip: true,
    status: 'NOT_FOUND',
    message_to_agent: 'Faltó la consulta. Pedile al cliente más detalle.',
    trace_id: $execution.id,
    session_id: sessionId
  } }];
}

// --- 1) Normalización -------------------------------------------------------
const q = raw.toLowerCase();
// NFD descompone "ú" en "u" + combinador U+0301. El rango U+0300–U+036F es
// "Combining Diacritical Marks" — los eliminamos para hacer match sin acentos.
const q_norm = q
  .normalize('NFD')
  .replace(/[̀-ͯ]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// --- 2) Tokenización + stopwords -------------------------------------------
const STOPWORDS = new Set([
  'hola','holaa','buenas','buenos','dias','tardes','noches',
  'quiero','queria','necesito','busco','me','interesa','interesaria',
  'mas','informacion','info','sobre','acerca','de','del','la','las','el','los',
  'un','una','unos','unas','y','o','con','para','por','que','como','cual',
  'cuales','si','no','tienen','tenes','tienes','tendrias','hay','hace','haces',
  'gracias','please','porfa','porfis','che','dale','tu','tus','su','sus','mi','mis'
]);

const tokensRaw = q_norm
  .replace(/[¿?¡!.,;:()\[\]{}"]/g, ' ')
  .split(/\s+/)
  .filter(Boolean);

const tokens = tokensRaw.filter(t => !STOPWORDS.has(t) && t.length >= 2);

// Si después de stripping no queda nada significativo → skip
if (tokens.length === 0) {
  return [{ json: {
    _skip: true,
    status: 'NOT_FOUND',
    message_to_agent: 'La consulta no trae información suficiente. Pedile al cliente que indique marca, tecnología o modelo.',
    trace_id: $execution.id,
    session_id: sessionId
  } }];
}

// --- 3) Helpers -------------------------------------------------------------
const esc = (s) => String(s).replace(/"/g, '\\"');
const stripSpacesDashes = (s) =>
  String(s).toUpperCase().replace(/[\s\-_/.]/g, '');

// --- 4) Extracción de hints --------------------------------------------------

// 4.a — MARCA (canonicalizada al singleSelect Airtable)
const BRAND_MAP = {
  'huenu':           'HUENU',
  'dlican':          'DLICAN',
  'teneth':          'TENETH',
  'hanrun':          'HANRUN',
  'xenons':          'XENONS',
  'riso':            'RISO',
  'sinajet':         'Sinajet',
  'konica minolta':  'Konica Minolta',
  'konica':          'Konica Minolta',
  'minolta':         'Konica Minolta',
  'bizhub':          'Konica Minolta',
  'accurio':         'Konica Minolta',
  'acurio':          'Konica Minolta',
};
let marca = '';
// Ordenamos por longitud descendente para que "konica minolta" gane a "konica"
const brandKeys = Object.keys(BRAND_MAP).sort((a, b) => b.length - a.length);
for (const k of brandKeys) {
  if (q_norm.includes(k)) { marca = BRAND_MAP[k]; break; }
}

// 4.b — TECNOLOGÍA (canonicalizada al linked record Airtable)
// Orden importa: keys específicos primero ("dtf textil" antes que "dtf", "\buv\b" al final).
const TECH_PATTERNS = [
  { re: /\bdtf\s*textil\b/,                  val: 'DTF Textil' },
  { re: /\bdtf\s*uv\b/,                      val: 'DTF UV' },
  { re: /\beco[\s-]?solvente\b/,             val: 'Eco-Solvente' },
  { re: /\bsublim/,                          val: 'Sublimación' },
  { re: /\bsolvente\b/,                      val: 'Solvente' },
  { re: /\bgran\s*formato\b/,                val: 'Gran Formato' },
  { re: /\b(idl|laser)\b/,                   val: 'IDL Láser' },
  { re: /\b(corte|plotter\s*de?\s*corte)\b/, val: 'Corte' },
  { re: /\briso\b/,                          val: 'RISO' },
  { re: /\bdtf\b/,                           val: 'DTF Textil' },
  { re: /\buv\b/,                            val: 'UV' },
];
let tecnologia = '';
for (const { re, val } of TECH_PATTERNS) {
  if (re.test(q_norm)) { tecnologia = val; break; }
}

// 4.c — FORMATO (canonicalizado al singleSelect Airtable, con acentos)
const FORMAT_MAP = {
  'cama plana':    'Cama Plana',
  'rollo a rollo': 'Rollo a Rollo',
  'rollo':         'Rollo a Rollo',
  'hibrido':       'Híbrido',
  'mesa':          'Mesa',
  'plotter':       'Plotter',
  'cilindrica':    'Cilíndrica',
  'pliego':        'Pliego',
  'bobina':        'Bobina',
  'compacta':      'Compacta',
  'horno':         'Horno',
  'purificador':   'Purificador',
  'plancha':       'Plancha',
};
let formato = '';
const formatKeys = Object.keys(FORMAT_MAP).sort((a, b) => b.length - a.length);
for (const k of formatKeys) {
  if (q_norm.includes(k)) { formato = FORMAT_MAP[k]; break; }
}

// 4.d — MODELO_HINT (regex sobre el RAW para preservar mayúsculas/dígitos)
// Patrones: "HF6090", "HF 6090", "HR1602SU", "DLI-1688", "X4E-7703", "TN48CCD",
//           "BIZHUB C450i" (segundo regex captura "C450i").
let modelo_hint = '';
const MODEL_REGEXES = [
  /\b([A-Z]{1,4}[\s\-_/.]?\d{2,5}[A-Z]{0,4})\b/i,
  /\b(C\d{3,4}i?)\b/i,
];
for (const re of MODEL_REGEXES) {
  const m = raw.match(re);
  if (m) { modelo_hint = stripSpacesDashes(m[1]); break; }
}
// Descartar false positives obvios
if (modelo_hint && /^(UV|DTF|RISO|IDL)$/i.test(modelo_hint)) modelo_hint = '';

// --- 5) Clasificación de intent ---------------------------------------------
let intent = 'equipo';
const RE_INVENTARIO = /\b(usad|refurbish|reaco|bizhub|accurio|acurio)\b|konica\s*minolt/i;
const RE_APLICACION = /\b(imprim|estamp|gorra|gorr|remera|bandera|wrap|cartel|vinil|sticker|adhesi|stand|prend|tela|algodon|polyester|aplicacion)/i;

if (RE_INVENTARIO.test(q_norm)) {
  intent = 'inventario';
} else if (RE_APLICACION.test(q_norm) && !marca && !modelo_hint) {
  // Solo es "aplicación" si NO menciona marca conocida ni modelo concreto
  intent = 'aplicacion';
}

// --- 6) Construcción de filterByFormula -------------------------------------
const F_modelo_match = (mh) =>
  `FIND("${esc(mh)}", UPPER(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE({Modelo}, " ", ""), "-", ""), "/", "")))>0`;
const F_marca = (m)   => `{Marca}="${esc(m)}"`;
const F_formato = (f) => `{Formato}="${esc(f)}"`;
const F_tec = (t)     => `FIND("${esc(t)}", ARRAYJOIN({Tecnología}))>0`;

// === EQUIPOS ===
let filterByFormula_equipos = '';
const eqParts = [];
if (modelo_hint) {
  // Caso 1: modelo identificado — best signal. Sumamos marca si la hay como refuerzo.
  eqParts.push(F_modelo_match(modelo_hint));
  if (marca) eqParts.push(F_marca(marca));
} else if (marca && tecnologia) {
  eqParts.push(F_marca(marca));
  eqParts.push(F_tec(tecnologia));
} else if (marca && formato) {
  eqParts.push(F_marca(marca));
  eqParts.push(F_formato(formato));
} else if (formato && tecnologia) {
  eqParts.push(F_formato(formato));
  eqParts.push(F_tec(tecnologia));
} else if (marca) {
  eqParts.push(F_marca(marca));
} else if (formato) {
  eqParts.push(F_formato(formato));
} else if (tecnologia) {
  eqParts.push(F_tec(tecnologia));
} else {
  // Fallback: tokens contra Modelo/Marca/Formato
  const tokenOr = tokens
    .filter(t => t.length >= 3)
    .slice(0, 6)
    .flatMap(t => [
      `SEARCH("${esc(t)}", LOWER({Modelo}))`,
      `SEARCH("${esc(t)}", LOWER({Marca}))`,
      `SEARCH("${esc(t)}", LOWER({Formato}))`,
    ]);
  if (tokenOr.length) {
    eqParts.push(`OR(${tokenOr.join(', ')})`);
  } else {
    eqParts.push(`FALSE()`);
  }
}
filterByFormula_equipos = eqParts.length > 1
  ? `AND(${eqParts.join(', ')})`
  : eqParts[0];

// === APLICACIONES ===
let filterByFormula_aplicaciones = '';
{
  const usefulTokens = tokens.filter(t => t.length >= 3).slice(0, 6);
  if (usefulTokens.length) {
    const parts = usefulTokens.flatMap(t => [
      `SEARCH("${esc(t)}", LOWER({Nombre}))`,
      `SEARCH("${esc(t)}", LOWER(ARRAYJOIN({Sustratos tipicos})))`,
    ]);
    filterByFormula_aplicaciones = `OR(${parts.join(', ')})`;
  } else {
    filterByFormula_aplicaciones = 'FALSE()';
  }
}

// === INVENTARIO KONICA ===
let filterByFormula_inventario = '';
if (modelo_hint) {
  filterByFormula_inventario = F_modelo_match(modelo_hint);
} else {
  const usefulTokens = tokens.filter(t => t.length >= 3).slice(0, 6);
  if (usefulTokens.length) {
    const parts = usefulTokens.flatMap(t => [
      `SEARCH("${esc(t)}", LOWER({Modelo}))`,
      `SEARCH("${esc(t)}", LOWER({Marca}))`,
    ]);
    filterByFormula_inventario = `OR(${parts.join(', ')})`;
  } else {
    filterByFormula_inventario = 'FALSE()';
  }
}

// --- 7) Output --------------------------------------------------------------
return [{
  json: {
    intent,
    query_raw: raw,
    query_lower: q,
    q_norm,
    marca,
    tecnologia,
    formato,
    modelo_hint,
    tokens,
    session_id: sessionId,
    trace_id: $execution.id,
    filterByFormula_equipos,
    filterByFormula_aplicaciones,
    filterByFormula_inventario,
  }
}];

// ============================================================================
// SYS — consultar_catalogo · Format Output v3
// Cambios vs v2:
//   - Agrega `formato`, `linea_producto`, `velocidad`, `cabezales_incluidos`,
//     `cabezales_tipo`, `datos_extra`, `tipo_uso` al output items[].
//   - NO incluye Precio (política cliente: el agente NUNCA da precios).
//   - El mensaje NOT_FOUND lista los hints extraídos (debug operativo).
// ============================================================================

const ctx = $('Classify Intent').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && (r.id || r.fields));

if (rows.length === 0) {
  return [{ json: {
    status: 'NOT_FOUND',
    data: null,
    message_to_agent: `No encontré coincidencias en el catálogo para "${ctx.query_raw}" (intent: ${ctx.intent}, marca: ${ctx.marca || '-'}, formato: ${ctx.formato || '-'}, tec: ${ctx.tecnologia || '-'}, modelo_hint: ${ctx.modelo_hint || '-'}). Pedile al cliente más detalle (marca, formato, modelo) o derivá al comercial.`,
    trace_id: ctx.trace_id,
    intent: ctx.intent
  } }];
}

const items = rows.slice(0, 5).map(r => {
  const f = r.fields || r;
  return {
    modelo:              f['Modelo'] || f['Nombre'] || '',
    marca:               f['Marca'] || '',
    tecnologia:          f['Tecnología'] || f['Tecnologia'] || [],
    formato:             f['Formato'] || '',
    linea_producto:      f['Línea de Producto'] || f['Linea de Producto'] || [],
    ancho:               f['Ancho'] || f['Ancho máx (mm)'] || '',
    velocidad:           f['Velocidad (m²/h)'] || f['Velocidad'] || '',
    descripcion:         f['Descripción corta'] || f['Descripcion corta'] || f['Descripción'] || '',
    aplicaciones:        f['Aplicaciones compatibles'] || [],
    sustratos:           f['Sustratos compatibles'] || f['Sustratos tipicos'] || [],
    cabezales_incluidos: f['Cabezales incluidos'] || null,
    cabezales_tipo:      f['Cabezales tipo'] || f['Cabezales'] || [],
    datos_extra:         f['Datos extra'] || '',
    tipo_uso:            f['Tipo de Uso'] || '',
    disponibilidad:      f['Disponibilidad zona'] || [],
    contador_copias:     f['Contador de copias'] || null,
    // Precio: NO se incluye por política del cliente.
  };
}).filter(it => it.modelo);

return [{ json: {
  status: items.length ? 'RESOLVED' : 'NOT_FOUND',
  data: { intent: ctx.intent, total: items.length, items },
  message_to_agent: items.length
    ? `Encontré ${items.length} match(es) en el catálogo (intent: ${ctx.intent}). Integrá los datos en tu respuesta sin inventar specs. Recordá: NO dar precios — derivar a representante comercial para cotización.`
    : `No encontré matches concretos para "${ctx.query_raw}". Pedile al cliente más detalle o derivá al comercial.`,
  trace_id: ctx.trace_id
} }];
